From bdc0c4a0f18fbb0f54c84f39affde02eb296da73 Mon Sep 17 00:00:00 2001
From: Martin Topholm <mph@hoth.dk>
Date: Tue, 20 Dec 2016 09:02:43 +0100
Subject: [PATCH] ui: fix ncurses errors

Fix NCURSES errors introduced in commit 94f8626 (main: split struct
target into main/module parts).

diff --git a/termio.c b/termio.c
index 8d5e13f..60adf87 100644
--- a/termio.c
+++ b/termio.c
@@ -369,21 +369,17 @@ termio_cleanup(void)
 			fprintf(stdout, "%c[2;32m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else if (C_flag && t->af == AF_INET)
-			fprintf(stdout, "%c[2;31m%*.*%sc[0m",
+			fprintf(stdout, "%c[2;31m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else
 			fprintf(stdout, "%*.*s", w_width, w_width, t->host);
 		if (w_width)
 			fputc(' ', stdout);
-		if (t->duplicate != NULL)
-			fprintf(stdout, "(duplicate of %s)", t->duplicate->host);
-		else {
-			for (i=ifirst; i<ilast; i++) {
-				if (i < t->npkts)
-					fputc(t->res[i % NUM], stdout);
-				else
-					fputc(' ', stdout);
-			}
+		for (i=ifirst; i<ilast; i++) {
+			if (i < t->npkts)
+				fputc(t->res[i % NUM], stdout);
+			else
+				fputc(' ', stdout);
 		}
 		fputc('\n', stdout);
 	}
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrect escape sequences in the `fprintf` function calls for terminal output, which were introduced during a previous commit that modified the structure of the code. This led to improper formatting of the output, resulting in NCURSES errors when rendering text in the terminal.

        Commit message:
        ui: fix ncurses errors

Fix NCURSES errors introduced in commit 94f8626 (main: split struct
target into main/module parts).  

        Patch:
          */
 void
 termio_cleanup(void)
 {
 #ifndef NCURSES
 	setvbuf(stdout, NULL, _IONBF, 0);
 	if (scrbuffer)
 		free(scrbuffer);
 	if (isatty(STDIN_FILENO))
 		tcsetattr(STDIN_FILENO, TCSAFLUSH, &oterm); // XXX: TCASOFT? see openssh
 #else /* NCURSES */
 	struct target *t;
 	int col, i;
 	int imax, ifirst, ilast;

 	t = list;
 	if (t == NULL)
 		return;

 	col = getmaxx(stdscr);
 	imax = MIN(t->npkts, col - labelwidth);
 	imax = MIN(imax, NUM);
 	ifirst = (t->npkts > imax ? t->npkts - imax : 0);
 	ilast = t->npkts;

 	endwin();
 	DL_FOREACH(list, t) {
 		if (C_flag && t->af == AF_INET6)
 			fprintf(stdout, "%c[2;32m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else if (C_flag && t->af == AF_INET)
-			fprintf(stdout, "%c[2;31m%*.*%sc[0m",
+			fprintf(stdout, "%c[2;31m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else
 			fprintf(stdout, "%*.*s", w_width, w_width, t->host);
 		if (w_width)
 			fputc(' ', stdout);
-		if (t->duplicate != NULL)
-			fprintf(stdout, "(duplicate of %s)", t->duplicate->host);
-		else {
-			for (i=ifirst; i<ilast; i++) {
-				if (i < t->npkts)
-					fputc(t->res[i % NUM], stdout);
-				else
-					fputc(' ', stdout);
-			}
+		for (i=ifirst; i<ilast; i++) {
+			if (i < t->npkts)
+				fputc(t->res[i % NUM], stdout);
+			else
+				fputc(' ', stdout);
 		}
 		fputc('\n', stdout);
 	}
 #endif /* !NCURSES */
 }
-- 


        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>
